import { useState } from 'react';
import {
  List, Card, Tag, Button, Space, Typography, Modal, Form, Input, Select, App as AntApp,
} from 'antd';
import { PlusOutlined } from '@ant-design/icons';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { useNavigate } from 'react-router';
import { api, getErrorMessage } from '../../lib/api';
import { RequestCategory } from '@phison/types';
import type { ResidentRequest } from '@phison/types';
import { formatDateTime } from '../../lib/formatters';

const { Title, Text } = Typography;

const STATUS_COLORS: Record<string, string> = {
  submitted: 'orange', acknowledged: 'blue', in_progress: 'cyan',
  resolved: 'green', closed: 'default', rejected: 'red',
};

export default function ResidentRequests() {
  const { message } = AntApp.useApp();
  const qc = useQueryClient();
  const navigate = useNavigate();
  const [open, setOpen] = useState(false);
  const [form] = Form.useForm();

  const { data: requests = [], isLoading } = useQuery({
    queryKey: ['my-requests'],
    queryFn: () => api.get<ResidentRequest[]>('/requests/my').then(r => r.data),
  });

  const createMutation = useMutation({
    mutationFn: (v: Record<string, unknown>) => api.post('/requests', v),
    onSuccess: () => {
      message.success('Request submitted');
      qc.invalidateQueries({ queryKey: ['my-requests'] });
      setOpen(false);
      form.resetFields();
    },
    onError: (e) => message.error(getErrorMessage(e)),
  });

  return (
    <Space direction="vertical" size={16} style={{ width: '100%' }}>
      <Space style={{ justifyContent: 'space-between', width: '100%' }}>
        <Title level={4} style={{ margin: 0 }}>My Requests</Title>
        <Button type="primary" icon={<PlusOutlined />} onClick={() => setOpen(true)}>
          New Request
        </Button>
      </Space>

      <List
        loading={isLoading}
        dataSource={requests}
        locale={{ emptyText: 'No requests yet' }}
        renderItem={req => (
          <List.Item>
            <Card
              style={{ width: '100%', cursor: 'pointer' }}
              onClick={() => navigate(`/resident/requests/${req.id}`)}
              styles={{ body: { padding: '16px 20px' } }}
            >
              <Space style={{ justifyContent: 'space-between', width: '100%' }}>
                <Space direction="vertical" size={4}>
                  <Text strong>{req.subject}</Text>
                  <Space>
                    <Tag>{req.category}</Tag>
                    <Text type="secondary" style={{ fontSize: 12 }}>{formatDateTime(req.createdAt)}</Text>
                  </Space>
                </Space>
                <Tag color={STATUS_COLORS[req.status]}>{req.status.replace(/_/g, ' ')}</Tag>
              </Space>
            </Card>
          </List.Item>
        )}
      />

      <Modal
        title="Submit a Request"
        open={open}
        onCancel={() => { setOpen(false); form.resetFields(); }}
        onOk={() => form.submit()}
        confirmLoading={createMutation.isPending}
      >
        <Form form={form} layout="vertical" onFinish={v => createMutation.mutate(v)}>
          <Form.Item name="category" label="Category" rules={[{ required: true }]}>
            <Select options={Object.values(RequestCategory).map(c => ({ label: c, value: c }))} />
          </Form.Item>
          <Form.Item name="subject" label="Subject" rules={[{ required: true }]}><Input /></Form.Item>
          <Form.Item name="description" label="Description" rules={[{ required: true }]}>
            <Input.TextArea rows={4} />
          </Form.Item>
        </Form>
      </Modal>
    </Space>
  );
}
